const fs = require\('fs'\);
const src = fs.readFileSync\('src/components/CarrierRef.jsx', 'utf8'\);
let b=0, p=0, s=0;
for \(const c of src\) {
  if \(c==='{'\) b++; if \(c==='}'\) b--;
  if \(c==='\('\) p++; if \(c==='\)'\) p--;
  if \(c==='['\) s++; if \(c===']'\) s--;
  if \(b<0||p<0||s<0\) { console.log\('NEGATIVE at', c\); break; }
}
console.log\('Braces:', b, 'Parens:', p, 'Brackets:', s\);
console.log\(b===0&&p===0&&s===0 ? 'BALANCED' : 'IMBALANCED'\);
console.log\('Lines:', src.split\('\\n'\).length\);
")

